<!-- report/analysis.vue -- pages.json 注册，对齐 AnalysisReport -->
<template><view class="p"><NavBar title="分析报告" :showBack="true"/><LoadingSkeleton v-if="ld"/><view v-else-if="r" class="b"><view class="h"><text class="sk">分析报告</text><text class="hi">#{{r.id}}</text></view><image v-if="img" :src="img" mode="aspectFit" class="im"/><view class="cd"><text class="ct">AI诊断结果</text><view v-if="r.findings?.length"><view v-for="(f,i) in r.findings" :key="i" class="fi"><text class="ft">{{f.type||'发现'}}</text><text class="fl" v-if="f.location">{{f.location}}</text><text class="fc">{{f.confidence!=null?(f.confidence*100).toFixed(1)+'%':'--'}}</text></view></view><text v-else class="no">暂无详细发现记录</text></view></view></view></template>
<script setup>
import{ref,onMounted}from'vue';import NavBar from'@/components/nav-bar.vue';import LoadingSkeleton from'@/components/loading-skeleton.vue';import{medicalAPI}from'@/api/medical';import{ensureImageUrl}from'@/utils/image'
const ld=ref(true);const r=ref(null);const img=ref('')
onMounted(async()=>{const id=getCurrentPages().pop()?.options?.id;if(!id)return;try{const d=await medicalAPI.getReportDetail(id);r.value=d?.data||d;img.value=ensureImageUrl(r.value?.imageUrl)}catch(e){}finally{ld.value=false}})
</script>
<style scoped>.p{min-height:100vh;background:#040b16}.b{padding:28rpx}.h{display:flex;flex-direction:column;gap:14rpx;margin-bottom:28rpx}.sk{display:inline-flex;padding:6rpx 16rpx;background:rgba(34,211,238,.08);border:1px solid rgba(34,211,238,.18);border-radius:999rpx;color:#86e9ff;font-size:22rpx;width:fit-content;font-weight:600}.hi{font-size:40rpx;font-weight:800;color:#f7fbff}.im{width:100%;min-height:400rpx;border-radius:20rpx;background:rgba(6,17,30,.9);margin-bottom:28rpx}.cd{padding:24rpx;border-radius:22rpx;background:linear-gradient(180deg,rgba(7,21,36,.94),rgba(4,12,24,.96));border:1px solid rgba(125,211,252,.12)}.ct{font-size:30rpx;font-weight:700;color:#f7fbff;margin-bottom:20rpx;display:block}.fi{padding:20rpx;border-radius:16rpx;background:rgba(8,20,35,.72);border:1px solid rgba(125,211,252,.08);margin-bottom:14rpx}.ft{font-size:28rpx;color:#f0f6ff;font-weight:600;display:block}.fl{font-size:24rpx;color:rgba(200,218,242,.65);display:block;margin-top:4rpx}.fc{font-size:22rpx;color:#70d6ff;display:block;margin-top:6rpx}.no{font-size:26rpx;color:rgba(200,218,242,.5);padding:40rpx 0;text-align:center}</style>
